script:
$ProgressPreference='SilentlyContinue'
$ErrorActionPreference='Stop'
$r=[ordered]@{scope='FINAL_READ_ONLY_HOST_STATE';utc=[DateTime]::UtcNow.ToString('o')}
$r.os=Get-CimInstance Win32_OperatingSystem | Select-Object Caption,Version,BuildNumber,OSArchitecture,@{Name='LastBootUpTimeUtc';Expression={$_.LastBootUpTime.ToUniversalTime().ToString('o')}}
$r.hypervisor_present=(Get-CimInstance Win32_ComputerSystem).HypervisorPresent
$r.services=@(Get-Service vmms,vmcompute -ErrorAction SilentlyContinue | Select-Object Name,@{Name='Status';Expression={$_.Status.ToString()}})
$r.commands=@(Get-Command Get-VM,New-VM,Get-VHD -ErrorAction SilentlyContinue | Select-Object Name,Source,@{Name='Version';Expression={$_.Version.ToString()}})
$r.pending_reboot=[ordered]@{component_servicing=(Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending');windows_update=(Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired')}
$r.ps_version=$PSVersionTable.PSVersion.ToString()
$r.powershell_executable=Get-Item 'C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe' | Select-Object FullName,Length,@{Name='FileVersion';Expression={$_.VersionInfo.FileVersion}}
$r | ConvertTo-Json -Depth 8
